\set ON_ERROR_STOP on
begin;
create function pg_temp.assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;end$$;
create function pg_temp.reject(q text,code text) returns void language plpgsql as $$begin begin execute q;exception when others then if sqlstate=code then return;end if;raise;end;raise exception 'FAIL accepted %',q;end$$;
select pg_temp.assert(not has_function_privilege('anon','public.save_paid_customer_field_draft(uuid,uuid,uuid,uuid,bigint,text,text,text,jsonb)','EXECUTE') and not has_function_privilege('authenticated','public.save_paid_customer_field_draft(uuid,uuid,uuid,uuid,bigint,text,text,text,jsonb)','EXECUTE') and has_function_privilege('service_role','public.save_paid_customer_field_draft(uuid,uuid,uuid,uuid,bigint,text,text,text,jsonb)','EXECUTE'),'server only save');
select pg_temp.assert(not has_function_privilege('service_role','public.save_paid_simple_draft_v1(uuid,uuid,uuid,uuid,bigint,text,text,text)','EXECUTE') and not has_function_privilege('service_role','public.get_paid_simple_draft_v1(uuid,uuid,uuid)','EXECUTE') and not has_function_privilege('service_role','public.publish_paid_simple_draft_v1(uuid,uuid,uuid,bigint,uuid,uuid,jsonb)','EXECUTE'),'no direct legacy bypass');
select pg_temp.assert((select bool_and(prosecdef and proconfig=array['search_path=pg_catalog']) from pg_proc where oid in('public.save_paid_customer_field_draft(uuid,uuid,uuid,uuid,bigint,text,text,text,jsonb)'::regprocedure,'public.save_paid_simple_draft(uuid,uuid,uuid,uuid,bigint,text,text,text)'::regprocedure,'public.get_paid_simple_draft(uuid,uuid,uuid)'::regprocedure,'public.publish_paid_simple_draft(uuid,uuid,uuid,bigint,uuid,uuid,jsonb)'::regprocedure)),'fixed definer paths');
select pg_temp.assert((select relrowsecurity and relforcerowsecurity from pg_class where oid='public.paid_simple_drafts'::regclass) and not has_table_privilege('service_role','public.paid_simple_drafts','SELECT') and not has_table_privilege('authenticated','public.paid_simple_drafts','UPDATE'),'private forced RLS unchanged');
insert into auth.users(id,email) values('49000000-0000-4000-8000-000000000001','fields-sql-owner@example.test'),('49000000-0000-4000-8000-000000000009','fields-sql-foreign@example.test');
insert into public.tenants(id,name,slug,timezone,currency) values('49000000-0000-4000-8000-000000000002','Fields','fields-sql','UTC','USD');
insert into public.tenant_members(tenant_id,user_id,role) values('49000000-0000-4000-8000-000000000002','49000000-0000-4000-8000-000000000001','BUSINESS_OWNER');
insert into public.services(id,tenant_id,name,archetype,currency,base_price,duration_minutes) values('49000000-0000-4000-8000-000000000003','49000000-0000-4000-8000-000000000002','Cleaning','simple','USD',12500,60);
create function pg_temp.save_fields(p_revision bigint,p_fields jsonb default '[{"id":"custom_access","kind":"text","label":"Access notes","required":false,"maxLength":500},{"id":"custom_contact","kind":"text","label":"Contact notes","required":true,"maxLength":100}]',p_flow uuid default '49000000-0000-4000-8000-000000000004') returns jsonb language sql as $$select public.save_paid_customer_field_draft('49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000002',p_flow,'49000000-0000-4000-8000-000000000003',p_revision,'Cleaning','#4f46e5','stacked',p_fields)$$;
select public.save_paid_simple_draft('49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000002','49000000-0000-4000-8000-000000000004','49000000-0000-4000-8000-000000000003',0,'Cleaning','#4f46e5','stacked');
select public.publish_paid_simple_draft('49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000002','49000000-0000-4000-8000-000000000004',1,'49000000-0000-4000-8000-000000000010','49000000-0000-4000-8000-000000000011','["https://checkout.example.test"]');
create temp table publication_before as select to_jsonb(f) flow,(select jsonb_agg(to_jsonb(v)) from public.flow_versions v) versions,(select jsonb_agg(to_jsonb(i)) from public.flow_installations i) installations from public.flows f;
select pg_temp.assert(pg_temp.save_fields(1)='{"schemaVersion":2,"flowId":"49000000-0000-4000-8000-000000000004","revision":2}'::jsonb,'exact CAS upgrade');
select pg_temp.assert((public.get_paid_simple_draft('49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000002','49000000-0000-4000-8000-000000000004')->>'schemaVersion')='2','full versioned GET');
select pg_temp.assert((public.owner_paid_simple_drafts('49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000002')->'drafts'->0->'customerFields'->0->>'id')='custom_access','discovery preserves fields and order');
select pg_temp.reject('select pg_temp.save_fields(1)','40001');
select pg_temp.reject($q$select public.save_paid_simple_draft('49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000002','49000000-0000-4000-8000-000000000004','49000000-0000-4000-8000-000000000003',2,'Cleaning','#4f46e5','stacked')$q$,'0A000');
select pg_temp.reject($q$select public.publish_paid_simple_draft('49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000002','49000000-0000-4000-8000-000000000004',2,'49000000-0000-4000-8000-000000000012','49000000-0000-4000-8000-000000000013','["https://checkout.example.test"]')$q$,'0A000');
select pg_temp.reject($q$update public.paid_simple_drafts set draft_schema_version=1,customer_fields='[]' where flow_id='49000000-0000-4000-8000-000000000004'$q$,'55000');
do $$declare base jsonb:='{"id":"custom_access","kind":"text","label":"Access notes","required":false,"maxLength":500}';bad jsonb;fields jsonb;begin
 for bad in select value from jsonb_array_elements('[{"id":"custom_name"},{"id":"custom_price"},{"id":"constructor"},{"kind":"quantity"},{"maxLength":0},{"maxLength":1001},{"maxLength":1.5},{"required":"true"},{"price":10},{"label":" untrimmed "},{"label":"bad\nlabel"},{"label":"bad\u0085label"}]') loop
  fields:=jsonb_build_array(base||bad);perform pg_temp.assert(not lumin.customer_draft_fields_valid(fields),'strict SQL field shape');perform pg_temp.reject(format('select pg_temp.save_fields(2,%L::jsonb)',fields::text),'22023');
 end loop;
 perform pg_temp.assert(not lumin.customer_draft_fields_valid(jsonb_build_array(base,base)),'duplicate IDs');
 perform pg_temp.assert(not lumin.customer_draft_fields_valid(jsonb_build_array(jsonb_set(base,'{label}',to_jsonb(repeat('😀',51))))),'UTF16 label bound');
 perform pg_temp.assert(lumin.customer_draft_fields_valid(jsonb_build_array(jsonb_set(base,'{label}',to_jsonb(repeat('😀',50))))),'UTF16 exact label bound');
end $$;
select pg_temp.save_fields(0,'[]','49000000-0000-4000-8000-000000000005');
select pg_temp.reject($q$select public.publish_paid_simple_draft('49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000002','49000000-0000-4000-8000-000000000005',1,'49000000-0000-4000-8000-000000000014','49000000-0000-4000-8000-000000000015','["https://checkout.example.test"]')$q$,'0A000');
select pg_temp.reject($q$select public.get_paid_simple_draft('49000000-0000-4000-8000-000000000009','49000000-0000-4000-8000-000000000002','49000000-0000-4000-8000-000000000004')$q$,'42501');
update public.tenant_members set role='BUSINESS_STAFF' where tenant_id='49000000-0000-4000-8000-000000000002';select pg_temp.reject('select pg_temp.save_fields(2)','42501');
select pg_temp.assert((select to_jsonb(f)=b.flow and (select jsonb_agg(to_jsonb(v)) from public.flow_versions v)=b.versions and (select jsonb_agg(to_jsonb(i)) from public.flow_installations i)=b.installations from public.flows f cross join publication_before b),'immutable publication unchanged by V2 drafts/denied publish');
select pg_temp.assert(not exists(select 1 from public.bookings) and not exists(select 1 from public.payments) and not exists(select 1 from public.capacity_holds) and not exists(select 1 from public.flow_sessions),'no customer financial writes');
rollback;
\echo PASS customer field draft ACL/private RLS/strict fields/CAS/legacy rejection/publish closed/immutable publication/no customer writes
